export const taskDefinitions: CanvasNodeDefinition[] = [{ type: "terminal-task", label: "Codex task", category: "Agents", ports: [{ id: "in", label: "IN", direction: "input", type: "message" }, { id: "out", label: "OUT", direction: "output", type: "message" }], defaults: {}, fields: [{key:"assignment",label:"Assignment",kind:"textarea",required:true}] }]
export function createTaskDocument(): CanvasDocument {
  return { schemaVersion: 1, id: "canvas-workbench", revision: 0, frames: [], notes: [], nodes: taskFixtures.map(task => ({ id: task.id, type: "terminal-task", title: task.title.en, position: task.id === "design" ? { x: 0, y: 0 } : { x: 680, y: task.id === "review" ? 530 : 0 }, config: {role:task.role,assignment:task.assignment.en} })), edges: [ { id: "research-review", source: "research", sourcePort: "out", target: "review", targetPort: "in" }, { id: "design-review", source: "design", sourcePort: "out", target: "review", targetPort: "in" } ] }
}
